        IndicationItem("ind_111", "Dental pain", 'D', "Dental & Analgesia", listOf("Ketorolac", "Ibuprofen", "Paracetamol", "Amoxicillin"), "NSAIDs first-line for inflammatory dental pulpitis; dental intervention."),
        IndicationItem("ind_112", "Depression", 'D', "Psychiatry", listOf("Escitalopram", "Sertraline", "Fluoxetine", "Amitriptyline"), "SSRIs first-line with minimum 6-9 months continuation after remission."),
        IndicationItem("ind_113", "Dermatitis", 'D', "Dermatology", listOf("Hydrocortisone", "Betamethasone", "Emollients", "Cetirizine"), "Topical corticosteroids for flares; daily thick emollients for barrier repair."),
        IndicationItem("ind_114", "Diabetes insipidus", 'D', "Endocrine & Nephrology", listOf("Desmopressin (DDAVP)", "Hydrochlorothiazide"), "DDAVP for central DI; thiazide diuretics and low-salt diet for nephrogenic DI."),
        IndicationItem("ind_115", "Diabetes mellitus", 'D', "Endocrine & Metabolic", listOf("Metformin", "Sitagliptin", "Glimepiride", "Insulin Glargine"), "Lifestyle + Metformin first-line; add SGLT2i or GLP-1 RA for ASCVD/CKD/HF."),
        IndicationItem("ind_116", "Diabetic foot ulcer", 'D', "Endocrine & Surgery", listOf("Piperacillin + Tazobactam", "Amoxicillin + Clavulanate", "Ciprofloxacin"), "Offloading, surgical debridement, glycemic optimization, broad polymicrobial coverage."),
        IndicationItem("ind_117", "Diabetic ketoacidosis", 'D', "Emergency & Endocrine", listOf("Regular Insulin", "Normal Saline", "Potassium Chloride"), "Fluid resuscitation, IV regular insulin infusion (0.1 U/kg/h), aggressive potassium repletion."),
        IndicationItem("ind_118", "Diabetic neuropathy", 'D', "Neurology & Endocrine", listOf("Gabapentin", "Pregabalin", "Duloxetine", "Amitriptyline"), "Strict glycemic control; Gabapentin, Pregabalin, or Duloxetine for neuropathic pain."),
        IndicationItem("ind_119", "Diarrhoea", 'D', "Gastrointestinal", listOf("Oral Rehydration Salts (ORS)", "Zinc Sulfate", "Loperamide", "Racecadotril"), "Hydration is cornerstone; avoid antimotility agents in fever or bloody stools."),
        IndicationItem("ind_120", "Digoxin toxicity", 'D', "Cardiovascular & Emergency", listOf("Digoxin-specific Fab antibodies", "Potassium", "Magnesium", "Atropine"), "Digoxin immune Fab (DigiFab) for life-threatening arrhythmias or hyperkalemia."),
        IndicationItem("ind_121", "Diverticulitis", 'D', "Gastrointestinal & Surgery", listOf("Ciprofloxacin + Metronidazole", "Amoxicillin + Clavulanate"), "Outpatient oral antibiotics for uncomplicated; bowel rest and IV antibiotics for complicated."),
        IndicationItem("ind_122", "Dizziness", 'D', "Neurology & ENT", listOf("Betahistine", "Cinnarizine", "Prochlorperazine"), "Differentiate vertigo (vestibular) from presyncope/disequilibrium; vestibular sedatives short-term."),
        IndicationItem("ind_123", "Duodenal ulcer", 'D', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Amoxicillin", "Clarithromycin", "Sucralfate"), "PPI for 4-8 weeks plus 14-day H. pylori eradication quadruple/triple therapy."),
        IndicationItem("ind_124", "Dysentery", 'D', "Infectious Diseases & GI", listOf("Azithromycin", "Ciprofloxacin", "Ceftriaxone", "Metronidazole"), "Oral rehydration, empirical coverage for Shigella/Campylobacter or Amoebic dysentery."),
        IndicationItem("ind_125", "Dyslipidemia", 'D', "Cardiovascular & Endocrine", listOf("Atorvastatin", "Rosuvastatin", "Fenofibrate", "Ezetimibe"), "Statins first-line; add Ezetimibe if target LDL-C not achieved; fibrates for triglycerides > 500."),
        IndicationItem("ind_126", "Dysmenorrhoea", 'D', "Gastrointestinal & Gynaecology", listOf("Mefenamic Acid", "Diclofenac", "Drotaverine", "Combined Oral Contraceptives"), "NSAIDs starting 1-2 days before menses to suppress excess endometrial prostaglandins."),
        IndicationItem("ind_127", "Dyspepsia", 'D', "Gastrointestinal", listOf("Pantoprazole", "Domperidone", "Antacids"), "Empiric trial of PPI; endoscopy for patients >55 years or with red flag alarm symptoms."),

        // --- E ---
        IndicationItem("ind_128", "Eclampsia", 'E', "Obstetrics & Emergency", listOf("Magnesium Sulfate", "Labetalol", "Hydralazine"), "Loading dose 4g IV Magnesium Sulfate followed by 1g/h infusion; urgent delivery."),
        IndicationItem("ind_129", "Eczema", 'E', "Dermatology", listOf("Betamethasone Cream", "Hydrocortisone", "Tacrolimus", "Emollients"), "Emollients applied liberally; intermittent topical corticosteroids; antihistamines for sleep."),
        IndicationItem("ind_130", "Emergency contraception", 'E', "Obstetrics & Gynaecology", listOf("Levonorgestrel 1.5mg", "Ulipristal Acetate", "Copper IUD"), "Levonorgestrel 1.5mg single dose within 72h of unprotected intercourse; Ulipristal within 120h."),
        IndicationItem("ind_131", "Endocarditis", 'E', "Cardiovascular & Infectious", listOf("Ceftriaxone", "Vancomycin", "Gentamicin", "Ampicillin"), "Prolonged bactericidal IV therapy (4-6 weeks) based on Duke criteria and blood cultures."),
        IndicationItem("ind_132", "Enteric fever", 'E', "Infectious Diseases", listOf("Ceftriaxone", "Azithromycin", "Cefixime"), "High-dose Ceftriaxone IV (2g daily) or Azithromycin PO (1g day 1 then 500mg daily x 6d)."),
        IndicationItem("ind_133", "Epilepsy", 'E', "Neurology", listOf("Levetiracetam", "Sodium Valproate", "Phenytoin", "Carbamazepine"), "Monotherapy with Levetiracetam or Sodium Valproate matched to seizure classification."),
        IndicationItem("ind_134", "Erectile dysfunction", 'E', "Urology & Endocrine", listOf("Sildenafil", "Tadalafil"), "PDE-5 inhibitors on-demand; strictly contraindicated with concurrent organic nitrates."),
        IndicationItem("ind_135", "Erysipelas", 'E', "Dermatology & Infectious", listOf("Penicillin V", "Amoxicillin", "Ceftriaxone"), "Penicillin or amoxicillin targeting Streptococcus pyogenes; limb elevation."),

        // --- F ---
        IndicationItem("ind_136", "Falciparum malaria", 'F', "Infectious Diseases", listOf("Artemether + Lumefantrine", "Artesunate IV", "Primaquine"), "ACT orally for uncomplicated; IV Artesunate 2.4 mg/kg at 0, 12, 24h for severe malaria."),
        IndicationItem("ind_137", "Febrile neutropenia", 'F', "Hematology & Oncology", listOf("Piperacillin + Tazobactam", "Meropenem", "Vancomycin"), "Emergency empiric antipseudomonal monotherapy within 1 hour of fever presentation."),
        IndicationItem("ind_138", "Fever", 'F', "Emergency & General", listOf("Paracetamol", "Diclofenac", "Ibuprofen"), "Oral/IV Paracetamol 10-15 mg/kg q4-6h (max 4g/day in adults); treat underlying cause."),
        IndicationItem("ind_139", "Fibromyalgia", 'F', "Rheumatology & Neurology", listOf("Pregabalin", "Duloxetine", "Amitriptyline"), "SNRI (Duloxetine) or alpha-2-delta ligand (Pregabalin) coupled with low-impact aerobic exercise."),
        IndicationItem("ind_140", "Flu", 'F', "Infectious Diseases & Respiratory", listOf("Oseltamivir", "Paracetamol", "Salbutamol"), "Oseltamivir 75mg PO bid within 48h of onset in high-risk patients; supportive antipyretics."),
        IndicationItem("ind_141", "Fungal infections", 'F', "Infectious Diseases & Mycology", listOf("Fluconazole", "Terbinafine", "Clotrimazole", "Itraconazole"), "Topical azoles for superficial dermatomycoses; oral fluconazole/itraconazole for systemic."),

        // --- G ---
        IndicationItem("ind_142", "GERD", 'G', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Domperidone", "Sucralfate"), "Full-dose PPI once daily 30-60 min before breakfast for 8 weeks."),
        IndicationItem("ind_143", "Gastric ulcer", 'G', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Sucralfate"), "Proton pump inhibitors for 8-12 weeks with repeat endoscopy to confirm healing."),
        IndicationItem("ind_144", "Gastritis", 'G', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Antacids", "Sucralfate"), "Acid suppression, discontinue NSAIDs and alcohol, test for H. pylori."),
        IndicationItem("ind_145", "Gastroenteritis", 'G', "Gastrointestinal", listOf("Oral Rehydration Salts (ORS)", "Zinc", "Ondansetron"), "Rehydration is paramount; antiemetic for persistent vomiting to allow oral intake."),
        IndicationItem("ind_146", "Generalised tonic-clonic seizures", 'G', "Neurology", listOf("Sodium Valproate", "Levetiracetam", "Phenytoin", "Diazepam"), "IV Lorazepam/Diazepam for acute termination; Valproate or Levetiracetam maintenance."),
        IndicationItem("ind_147", "Generalized anxiety disorder", 'G', "Psychiatry", listOf("Escitalopram", "Sertraline", "Buspirone", "Alprazolam"), "First-line SSRIs with cognitive behavioral therapy; avoid long-term benzodiazepines."),
        IndicationItem("ind_148", "Genital herpes", 'G', "Infectious Diseases & STI", listOf("Acyclovir", "Valacyclovir"), "Oral Acyclovir 400mg tid for 7-10 days for primary episode; episodic therapy for recurrences."),
        IndicationItem("ind_149", "Giardiasis", 'G', "Infectious Diseases & GI", listOf("Metronidazole", "Tinidazole"), "Metronidazole 250mg tid for 5-7 days or Tinidazole 2g single dose."),
        IndicationItem("ind_150", "Glaucoma", 'G', "Ophthalmology", listOf("Timolol Eye Drops", "Latanoprost", "Brimonidine", "Acetazolamide"), "Topical prostaglandin analogue (Latanoprost) or beta-blocker (Timolol) to reduce IOP."),
        IndicationItem("ind_151", "Gonorrhoea", 'G', "Infectious Diseases & STI", listOf("Ceftriaxone", "Azithromycin"), "Single dose Ceftriaxone 500mg-1g IM plus Azithromycin 1g PO."),
        IndicationItem("ind_152", "Gout", 'G', "Musculoskeletal", listOf("Allopurinol", "Febuxostat", "Diclofenac", "Colchicine"), "NSAID/colchicine for acute flare; Allopurinol (target serum urate < 6 mg/dL) for prophylaxis."),

        // --- H ---
        IndicationItem("ind_153", "H. pylori infection", 'H', "Gastrointestinal", listOf("Pantoprazole", "Amoxicillin", "Clarithromycin", "Metronidazole"), "14-day triple therapy (PPI + Amox + Clarithromycin) or bismuth quadruple therapy."),
        IndicationItem("ind_154", "Headache", 'H', "Neurology", listOf("Paracetamol", "Diclofenac", "Sumatriptan", "Naproxen"), "Differentiate primary (migraine, tension) from secondary life-threatening headache."),
        IndicationItem("ind_155", "Heart failure", 'H', "Cardiovascular", listOf("Ramipril", "Bisoprolol", "Spironolactone", "Furosemide", "Dapagliflozin"), "GDMT quadruple therapy with loop diuretics titrated to euvolemic state."),
        IndicationItem("ind_156", "Helminthiasis", 'H', "Infectious Diseases", listOf("Albendazole", "Mebendazole"), "Albendazole 400mg single dose orally with fatty meal; repeat in 2 weeks for enterobiasis."),
        IndicationItem("ind_157", "Hepatic encephalopathy", 'H', "Gastroenterology", listOf("Lactulose", "Rifaximin"), "Lactulose titrated to 2-3 soft bowel movements daily; add Rifaximin for recurrence."),
        IndicationItem("ind_158", "Hepatitis B virus", 'H', "Gastroenterology & Infectious", listOf("Tenofovir Disoproxil", "Entecavir"), "Potent nucleoside/nucleotide reverse transcriptase inhibitors with high barrier to resistance."),
        IndicationItem("ind_159", "Hepatitis C virus", 'H', "Gastroenterology & Infectious", listOf("Sofosbuvir + Velpatasvir"), "Direct-acting antiviral (DAA) pangenotypic regimen for 12 weeks yields >95% SVR."),
        IndicationItem("ind_160", "Herpes zoster (shingles)", 'H', "Infectious Diseases & Dermatology", listOf("Acyclovir", "Valacyclovir", "Paracetamol", "Pregabalin"), "Oral Acyclovir 800mg 5 times daily for 7 days initiated within 72h of rash."),
        IndicationItem("ind_161", "High Cholesterol", 'H', "Cardiovascular & Endocrine", listOf("Atorvastatin", "Rosuvastatin", "Ezetimibe"), "High-intensity statin to lower LDL-C by ≥50%."),
        IndicationItem("ind_162", "Hyperglycemia", 'H', "Endocrine & Metabolic", listOf("Regular Insulin", "Metformin", "Sitagliptin"), "Target fasting blood glucose 80-130 mg/dL and postprandial < 180 mg/dL."),
        IndicationItem("ind_163", "Hyperkalemia", 'H', "Emergency & Nephrology", listOf("Calcium Gluconate", "Regular Insulin + Dextrose", "Salbutamol", "Furosemide"), "IV Calcium Gluconate 10% 10mL over 2-3 min for myocardial membrane stabilization."),
        IndicationItem("ind_164", "Hypertension", 'H', "Cardiovascular", listOf("Telmisartan", "Amlodipine", "Ramipril", "Bisoprolol", "Chlorthalidone"), "Initial dual therapy (ARB/ACEI + CCB or Thiazide); target BP < 130/80 mmHg."),
        IndicationItem("ind_165", "Hypertensive crisis", 'H', "Cardiovascular & Emergency", listOf("Labetalol", "Nitroglycerin", "Sodium Nitroprusside", "Nicardipine"), "Reduce MAP by no more than 25% within the first hour in emergency."),
        IndicationItem("ind_166", "Hyperthyroidism", 'H', "Endocrine", listOf("Carbimazole", "Propylthiouracil", "Propranolol"), "Antithyroid thionamides; Propranolol for rapid control of adrenergic symptoms."),
        IndicationItem("ind_167", "Hypoglycemia", 'H', "Emergency & Endocrine", listOf("Dextrose 25% or 50% IV", "Glucagon", "Oral Glucose Tablets"), "Rule of 15: 15-20g rapid-acting carbohydrate orally; IV 25% Dextrose 100mL if unconscious."),
        IndicationItem("ind_168", "Hypokalemia", 'H', "Emergency & Nephrology", listOf("Potassium Chloride (Oral / IV)", "Spironolactone"), "Oral potassium chloride preferred; IV infusion rate not to exceed 10-20 mEq/h with cardiac monitoring."),
        IndicationItem("ind_169", "Hypothyroidism", 'H', "Endocrine", listOf("Levothyroxine Sodium (T4)"), "Levothyroxine 1.6 mcg/kg/day taken fasting with plain water 30-60 min before breakfast."),
        IndicationItem("ind_170", "Hypovolaemic shock", 'H', "Emergency & Critical Care", listOf("Normal Saline", "Ringer Lactate", "Blood Transfusion", "Norepinephrine"), "Immediate crystalloid bolus (30 mL/kg); blood products for hemorrhagic shock."),

        // --- I ---
        IndicationItem("ind_171", "Impetigo", 'I', "Dermatology & Infectious", listOf("Mupirocin Ointment", "Amoxicillin + Clavulanate", "Cephalexin"), "Topical Mupirocin 2% tid for localized; oral antibiotics for widespread lesions."),
        IndicationItem("ind_172", "Infective endocarditis", 'I', "Cardiovascular & Infectious", listOf("Ceftriaxone", "Vancomycin", "Gentamicin", "Ampicillin"), "High-dose bactericidal IV therapy for 4-6 weeks with surveillance blood cultures."),
        IndicationItem("ind_173", "Inflammatory bowel disease", 'I', "Gastrointestinal", listOf("Mesalazine", "Prednisolone", "Azathioprine", "Infliximab"), "5-ASA for induction/maintenance in ulcerative colitis; systemic steroids for acute flares."),
        IndicationItem("ind_174", "Influenza", 'I', "Infectious Diseases & Respiratory", listOf("Oseltamivir", "Paracetamol"), "Neuraminidase inhibitor (Oseltamivir) initiated within 48h reduces symptom duration."),
        IndicationItem("ind_175", "Insomnia", 'I', "Psychiatry & Neurology", listOf("Zolpidem", "Melatonin", "Zopiclone", "Trazodone"), "Sleep hygiene first-line; short-term non-benzodiazepine hypnotics (Z-drugs) limited to 2-4 weeks."),
        IndicationItem("ind_176", "Intestinal amoebiasis", 'I', "Gastrointestinal", listOf("Metronidazole", "Tinidazole", "Diloxanide Furoate"), "Metronidazole 400-800mg tid x 7-10d followed by luminal agent."),
        IndicationItem("ind_177", "Intra-abdominal infections", 'I', "Surgery & Infectious", listOf("Piperacillin + Tazobactam", "Ceftriaxone + Metronidazole", "Meropenem"), "Coverage for enteric gram-negatives and anaerobes combined with surgical source control."),
        IndicationItem("ind_178", "Iron deficiency anemia", 'I', "Hematology", listOf("Ferrous Sulfate", "Iron Sucrose", "Ferric Carboxymaltose"), "Oral elemental iron 100-200 mg daily for 3 months after Hb normalizes; IV iron for intolerance."),
        IndicationItem("ind_179", "Irritable bowel syndrome (IBS)", 'I', "Gastrointestinal", listOf("Mebeverine", "Lactulose", "Loperamide", "Amitriptyline"), "Antispasmodics for pain; fiber/laxatives for IBS-C; loperamide for IBS-D; low-dose TCA."),
        IndicationItem("ind_180", "Ischemic stroke", 'I', "Neurology & Emergency", listOf("Alteplase (rtPA)", "Aspirin", "Atorvastatin", "Labetalol"), "IV thrombolysis with alteplase within 4.5h; Aspirin 150-300mg within 24-48h."),

        // --- K, L ---
        IndicationItem("ind_181", "Kala-azar (Visceral leishmaniasis)", 'K', "Infectious Diseases", listOf("Liposomal Amphotericin B", "Miltefosine"), "Single-dose Liposomal Amphotericin B (10 mg/kg IV) is first-line regimen in South Asia."),
        IndicationItem("ind_182", "Legionnaire's disease", 'L', "Respiratory & Infectious", listOf("Levofloxacin", "Azithromycin", "Moxifloxacin"), "Respiratory fluoroquinolone or macrolide with excellent intracellular tissue penetration."),
        IndicationItem("ind_183", "Leprosy", 'L', "Infectious Diseases & Dermatology", listOf("Rifampicin", "Dapsone", "Clofazimine"), "WHO multidrug therapy (MDT) for 6-12 months according to paucibacillary vs multibacillary."),
        IndicationItem("ind_184", "Liver cirrhosis", 'L', "Gastroenterology", listOf("Spironolactone", "Furosemide", "Lactulose", "Propranolol"), "Diuretics, dietary sodium restriction, screening for varices and hepatocellular carcinoma."),
        IndicationItem("ind_185", "Low back pain", 'L', "Musculoskeletal", listOf("Paracetamol", "Diclofenac", "Thiocolchicoside", "Pregabalin"), "Stay active, simple NSAID short-term; avoid prolonged bed rest or routine imaging."),

        // --- M ---
        IndicationItem("ind_186", "Major depressive disorder", 'M', "Psychiatry", listOf("Escitalopram", "Sertraline", "Fluoxetine", "Venlafaxine"), "SSRI or SNRI; monitor closely for suicide risk in young adults during initial weeks."),
        IndicationItem("ind_187", "Malaria", 'M', "Infectious Diseases", listOf("Artemether + Lumefantrine", "Artesunate", "Chloroquine"), "ACT for P. falciparum; Chloroquine + Primaquine (14d) for radical cure of P. vivax."),
        IndicationItem("ind_188", "Meningitis", 'M', "Infectious Diseases & Emergency", listOf("Ceftriaxone", "Vancomycin", "Dexamethasone", "Ampicillin"), "Stat blood cultures and immediate empiric IV bactericidal antibiotics without delay."),
        IndicationItem("ind_189", "Migraine", 'M', "Neurology", listOf("Sumatriptan", "Diclofenac", "Paracetamol", "Propranolol", "Amitriptyline"), "Triptan/NSAID abortive; Propranolol, Amitriptyline, or Topiramate for prophylaxis (≥3-4 attacks/mo)."),
        IndicationItem("ind_190", "Myasthenia gravis", 'M', "Neurology", listOf("Pyridostigmine", "Prednisolone", "Azathioprine", "IVIG"), "Acetylcholinesterase inhibitor (Pyridostigmine); avoid aminoglycosides and fluoroquinolones."),
        IndicationItem("ind_191", "Myocardial infarction", 'M', "Cardiovascular & Emergency", listOf("Aspirin", "Clopidogrel", "Atorvastatin", "Enoxaparin", "Metoprolol"), "Aspirin 300mg + Clopidogrel 300-600mg loading, statin 80mg, urgent reperfusion."),

        // --- N, O ---
        IndicationItem("ind_192", "NSAID-induced ulcers", 'N', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Misoprostol"), "Discontinue NSAID; high-dose PPI for 8 weeks; switch to selective COX-2 or paracetamol."),
        IndicationItem("ind_193", "Nasal congestion", 'N', "ENT & Respiratory", listOf("Xylometazoline Nasal Drops", "Fluticasone Nasal Spray"), "Topical nasal decongestants limited strictly to 3-5 days to avoid rhinitis medicamentosa."),
        IndicationItem("ind_194", "Nausea and vomiting", 'N', "Gastrointestinal & Emergency", listOf("Ondansetron", "Domperidone", "Metoclopramide"), "5-HT3 antagonist (Ondansetron) or dopamine antagonist (Metoclopramide)."),
        IndicationItem("ind_195", "Neonatal sepsis", 'N', "Pediatrics & Neonatology", listOf("Ampicillin", "Gentamicin", "Cefotaxime"), "Empiric Ampicillin + Gentamicin covering Group B Strep and Listeria; adjust by cultures."),
        IndicationItem("ind_196", "Nephrotic syndrome", 'N', "Nephrology & Pediatrics", listOf("Prednisolone", "Furosemide", "Ramipril", "Atorvastatin"), "High-dose oral prednisolone (60 mg/m2/day) in minimal change disease; sodium restriction."),
        IndicationItem("ind_197", "Neuropathic pain", 'N', "Neurology", listOf("Gabapentin", "Pregabalin", "Amitriptyline", "Duloxetine"), "First-line Gabapentin/Pregabalin or SNRI; titrate gradually to therapeutic dose."),
        IndicationItem("ind_198", "Nosocomial pneumonia", 'N', "Respiratory & Critical Care", listOf("Piperacillin + Tazobactam", "Meropenem", "Vancomycin", "Amikacin"), "Coverage for Pseudomonas aeruginosa and MRSA; adjust by local antibiogram."),
        IndicationItem("ind_199", "Obesity", 'O', "Endocrine & Metabolic", listOf("Orlistat", "Semaglutide", "Liraglutide"), "Lifestyle modification with calorie deficit; GLP-1 receptor agonists produce substantial weight loss."),
        IndicationItem("ind_200", "Obsessive-compulsive disorder (OCD)", 'O', "Psychiatry", listOf("Sertraline", "Fluoxetine", "Clomipramine"), "High-dose SSRIs for minimum 12 weeks combined with Exposure and Response Prevention (ERP)."),
        IndicationItem("ind_201", "Open-angle glaucoma", 'O', "Ophthalmology", listOf("Latanoprost", "Timolol", "Brimonidine", "Dorzolamide"), "Target IOP reduction of 25-30% with topical prostaglandin analogues as initial choice."),
        IndicationItem("ind_202", "Opioid overdose", 'O', "Emergency & Toxicology", listOf("Naloxone", "Airway & Ventilatory Support"), "IV/IM/Intranasal Naloxone 0.4-2mg; repeat q2-3min until spontaneous ventilation restored."),
        IndicationItem("ind_203", "Oral candidiasis/Thrush", 'O', "Infectious Diseases & Dental", listOf("Clotrimazole Troche", "Fluconazole", "Nystatin Suspension"), "Clotrimazole troches 10mg 5x/day or oral Fluconazole 100-200mg daily for 7-14 days."),
        IndicationItem("ind_204", "Organophosphorous poisoning", 'O', "Emergency & Toxicology", listOf("Atropine Sulfate", "Pralidoxime (2-PAM)"), "Atropine 2-5mg IV every 5-10 min until full atropinization (clear lungs, HR>80, dry skin)."),
        IndicationItem("ind_205", "Osteoarthritis", 'O', "Musculoskeletal", listOf("Paracetamol", "Diclofenac", "Ibuprofen", "Topical NSAID"), "Weight reduction, physical therapy, topical NSAIDs first; oral NSAIDs lowest dose/duration."),
        IndicationItem("ind_206", "Osteoporosis", 'O', "Endocrine & Rheumatology", listOf("Alendronate Sodium", "Zoledronic Acid", "Calcium Carbonate", "Vitamin D3"), "Oral bisphosphonate taken upright with full glass of water on empty stomach."),
        IndicationItem("ind_207", "Otitis media", 'O', "ENT & Pediatrics", listOf("Amoxicillin + Clavulanate", "Cefixime", "Paracetamol"), "First-line high-dose Amoxicillin; analgesics; watchful waiting in low-risk children >2 years."),

        // --- P ---
        IndicationItem("ind_208", "Panic disorder", 'P', "Psychiatry", listOf("Sertraline", "Escitalopram", "Alprazolam", "Clonazepam"), "SSRIs maintenance; short-term benzodiazepine bridging during first 2-3 weeks."),
        IndicationItem("ind_209", "Paracetamol poisoning", 'P', "Emergency & Toxicology", listOf("N-Acetylcysteine (NAC)"), "IV N-acetylcysteine according to Rumack-Matthew nomogram; most effective within 8 hours."),
        IndicationItem("ind_210", "Parkinson's disease", 'P', "Neurology", listOf("Levodopa + Carbidopa", "Pramipexole", "Trihexyphenidyl", "Rasagiline"), "Levodopa-carbidopa is most effective; dopamine agonists for younger patients."),
        IndicationItem("ind_211", "Paroxysmal supraventricular tachycardia", 'P', "Cardiovascular & Emergency", listOf("Adenosine", "Verapamil", "Metoprolol"), "Vagal maneuvers first; rapid IV push Adenosine (6mg then 12mg) through large antecubital vein."),
        IndicationItem("ind_212", "Pelvic inflammatory disease", 'P', "Infectious Diseases & Gynaecology", listOf("Ceftriaxone", "Doxycycline", "Metronidazole"), "Ceftriaxone 500mg IM single dose + Doxycycline 100mg PO bid + Metronidazole 500mg bid for 14 days."),
        IndicationItem("ind_213", "Peptic ulcer disease", 'P', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Amoxicillin", "Clarithromycin", "Sucralfate"), "Proton pump inhibitors + H. pylori eradication therapy for 14 days."),
        IndicationItem("ind_214", "Piles (Haemorrhoids)", 'P', "Surgery & Proctology", listOf("Lignocaine + Hydrocortisone Ointment", "Ispaghula Husk", "Flavonoids"), "High-fiber diet, warm sitz baths, stool softeners; short-term topical hydrocortisone."),
        IndicationItem("ind_215", "Pneumonia", 'P', "Respiratory & Infectious", listOf("Amoxicillin + Clavulanate", "Azithromycin", "Ceftriaxone", "Levofloxacin"), "Severity stratification with CURB-65; combination beta-lactam + macrolide."),
        IndicationItem("ind_216", "Post-herpetic neuralgia", 'P', "Neurology & Dermatology", listOf("Pregabalin", "Gabapentin", "Amitriptyline", "Capsaicin Cream"), "Alpha-2-delta ligands (Pregabalin 75-150mg bid) or tricyclic antidepressants."),
        IndicationItem("ind_217", "Pre-eclampsia", 'P', "Obstetrics & Emergency", listOf("Labetalol", "Nifedipine", "Magnesium Sulfate"), "Control severe hypertension (target 130-150 / 80-100); Magnesium sulfate for seizure prophylaxis."),
        IndicationItem("ind_218", "Prostate carcinoma", 'P', "Oncology & Urology", listOf("Bicalutamide", "Leuprolide", "Docetaxel"), "Androgen deprivation therapy (GnRH agonist + antiandrogen) for advanced disease."),
        IndicationItem("ind_219", "Prostatitis", 'P', "Urology & Infectious", listOf("Ciprofloxacin", "Levofloxacin", "Doxycycline"), "Prolonged fluoroquinolone course (4-6 weeks for chronic bacterial prostatitis)."),
        IndicationItem("ind_220", "Psoriasis", 'P', "Dermatology", listOf("Clobetasol", "Calcipotriol", "Methotrexate", "Acitretin"), "Topical corticosteroid + vitamin D analogue for plaque; systemic methotrexate for severe."),
        IndicationItem("ind_221", "Pulmonary embolism", 'P', "Cardiovascular & Emergency", listOf("Enoxaparin", "Apixaban", "Alteplase", "Warfarin"), "Therapeutic anticoagulation immediately; systemic thrombolysis for massive hemodynamically unstable PE."),
        IndicationItem("ind_222", "Pyelonephritis", 'P', "Urology & Infectious", listOf("Ceftriaxone", "Ciprofloxacin", "Piperacillin + Tazobactam"), "Parenteral Ceftriaxone or fluoroquinolone for 10-14 days; urine culture essential."),

        // --- R ---
        IndicationItem("ind_223", "Rabies prophylaxis", 'R', "Vaccines & Emergency", listOf("Rabies Vaccine", "Rabies Immunoglobulin (RIG)"), "Wound washing with soap & water for 15 min; RIG infiltrated around bite; vaccine on D 0, 3, 7, 28."),
        IndicationItem("ind_224", "Reflux oesophagitis", 'R', "Gastrointestinal", listOf("Pantoprazole", "Omeprazole", "Ranitidine"), "PPI healing dose once daily for 8 weeks; lifestyle modifications."),
        IndicationItem("ind_225", "Renal colic", 'R', "Urology & Emergency", listOf("Diclofenac", "Ketorolac", "Tamsulosin", "Morphine"), "NSAIDs provide rapid analgesia by lowering renal pelvic pressure; Tamsulosin for expulsion."),
        IndicationItem("ind_226", "Rheumatic fever", 'R', "Cardiovascular & Pediatrics", listOf("Benzathine Penicillin G", "Aspirin", "Prednisolone"), "Benzathine penicillin 1.2 MU IM single dose; high-dose aspirin for arthritis; secondary prophylaxis."),
        IndicationItem("ind_227", "Rheumatoid Arthritis (RA)", 'R', "Rheumatology", listOf("Methotrexate", "Tofacitinib", "Hydroxychloroquine", "Prednisolone", "Sulfasalazine", "Leflunomide"), "Early disease-modifying therapy (Methotrexate); JAK inhibitors (Tofacitinib, Baricitinib) for inadequate response; short-course steroid bridge."),
        IndicationItem("ind_228", "Rickets", 'R', "Pediatrics & Endocrine", listOf("Cholecalciferol (Vitamin D3)", "Calcium Carbonate"), "High-dose Vitamin D3 (e.g. 50,000 IU weekly for 6 weeks or stoss dose) with elemental calcium."),
        IndicationItem("ind_229", "Ringworm (Tinea corporis)", 'R', "Dermatology", listOf("Clotrimazole Cream", "Terbinafine Cream", "Fluconazole"), "Topical terbinafine or clotrimazole applied 2-3 cm beyond margin for 2 weeks."),
        IndicationItem("ind_230", "Rosacea", 'R', "Dermatology", listOf("Metronidazole Topical Gel", "Doxycycline", "Ivermectin Cream"), "Topical metronidazole 0.75% or ivermectin; low-dose anti-inflammatory oral doxycycline."),

        // --- S ---
        IndicationItem("ind_231", "SLE (Systemic Lupus Erythematosus)", 'S', "Rheumatology", listOf("Hydroxychloroquine", "Prednisolone", "Mycophenolate Mofetil"), "Hydroxychloroquine for all patients; glucocorticoids + immunosuppressive for organ flares."),
        IndicationItem("ind_232", "Scabies", 'S', "Dermatology & Infectious", listOf("Permethrin 5% Cream", "Ivermectin Oral"), "Permethrin 5% cream neck-to-toe overnight, wash after 8-14h; treat all household contacts."),
        IndicationItem("ind_233", "Schizophrenia", 'S', "Psychiatry", listOf("Olanzapine", "Risperidone", "Haloperidol", "Aripiprazole"), "Second-generation antipsychotics first-line; monitor metabolic parameters (weight, lipids, glucose)."),
        IndicationItem("ind_234", "Scrub typhus", 'S', "Infectious Diseases", listOf("Doxycycline", "Azithromycin", "Chloramphenicol"), "Doxycycline 100mg PO/IV bid for 7 days is drug of choice; Azithromycin safe in pregnancy/children."),
        IndicationItem("ind_235", "Sepsis", 'S', "Emergency & Critical Care", listOf("Piperacillin + Tazobactam", "Ceftriaxone", "Normal Saline", "Norepinephrine"), "Hour-1 bundle: blood cultures, broad-spectrum IV antibiotics, 30 mL/kg crystalloids, vasopressor."),
        IndicationItem("ind_236", "Septic shock", 'S', "Emergency & Critical Care", listOf("Norepinephrine", "Normal Saline", "Piperacillin + Tazobactam", "Hydrocortisone"), "Norepinephrine first-choice vasopressor to maintain MAP ≥ 65 mmHg; stress-dose hydrocortisone if refractory."),
        IndicationItem("ind_237", "Severe allergic asthma", 'S', "Respiratory", listOf("Salbutamol", "Hydrocortisone", "Ipratropium Bromide", "Omalizumab"), "Nebulized bronchodilators, high-dose IV corticosteroids, continuous monitoring."),
        IndicationItem("ind_238", "Shigellosis", 'S', "Infectious Diseases & GI", listOf("Azithromycin", "Ciprofloxacin", "Ceftriaxone"), "Azithromycin 500mg daily for 3 days or Ceftriaxone for invasive bacterial dysentery."),
        IndicationItem("ind_239", "Sinusitis", 'S', "ENT & Respiratory", listOf("Amoxicillin + Clavulanate", "Fluticasone Nasal Spray", "Xylometazoline"), "Antibiotics indicated if symptoms persist >10 days or severe 'double sickening'."),
        IndicationItem("ind_240", "Skin and soft tissue infections", 'S', "Dermatology & Infectious", listOf("Amoxicillin + Clavulanate", "Cloxacillin", "Cephalexin", "Vancomycin"), "Stratify purulent vs non-purulent; incision and drainage for abscess; antibiotics for cellulitis."),
        IndicationItem("ind_241", "Status epilepticus", 'S', "Neurology & Emergency", listOf("Lorazepam IV", "Diazepam", "Levetiracetam", "Phenytoin"), "IV Lorazepam 4mg (0.1 mg/kg) at 0-5 min; repeat once; IV Levetiracetam 60 mg/kg at 10-20 min."),
        IndicationItem("ind_242", "Stevens-Johnson syndrome", 'S', "Dermatology & Emergency", listOf("IVIG", "Cyclosporine", "Burn Unit Care"), "Immediate withdrawal of offending drug; fluid and wound care in burn/ICU setting."),
        IndicationItem("ind_243", "Streptococcal pharyngitis", 'S', "ENT & Infectious", listOf("Amoxicillin", "Penicillin V", "Azithromycin"), "Oral Amoxicillin 500mg bid for 10 days to prevent acute rheumatic fever."),
        IndicationItem("ind_244", "Stroke (Ischemic)", 'S', "Neurology & Emergency", listOf("Alteplase", "Aspirin", "Atorvastatin", "Labetalol"), "Thrombolysis within 4.5h window; antiplatelet, high-intensity statin, neuroprotection."),
        IndicationItem("ind_245", "Syphilis", 'S', "Infectious Diseases & STI", listOf("Benzathine Penicillin G", "Doxycycline"), "Benzathine Penicillin G 2.4 MU IM single dose for primary/secondary; 3 weekly doses for latent."),

        // --- T ---
        IndicationItem("ind_246", "Thyroid storm", 'T', "Endocrine & Emergency", listOf("Propylthiouracil", "Lugol's Iodine", "Propranolol", "Hydrocortisone"), "Antithyroid drug, Lugol's iodine after 1 hour, Propranolol for adrenergic block, IV Hydrocortisone."),
        IndicationItem("ind_247", "Thyrotoxicosis", 'T', "Endocrine", listOf("Carbimazole", "Propylthiouracil", "Propranolol"), "Carbimazole 15-40mg daily titrated to free T4; Propranolol for palpitations."),
        IndicationItem("ind_248", "Tinea capitis", 'T', "Dermatology & Pediatrics", listOf("Griseofulvin", "Terbinafine Oral"), "Systemic antifungal required for hair follicle penetration; topical alone is ineffective."),
        IndicationItem("ind_249", "Tonsillitis", 'T', "ENT & Infectious", listOf("Amoxicillin", "Paracetamol", "Azithromycin"), "Supportive analgesia; oral penicillin or amoxicillin for confirmed bacterial streptococcal infection."),
        IndicationItem("ind_250", "Toothache", 'T', "Dental & Analgesia", listOf("Ketorolac", "Paracetamol", "Ibuprofen"), "NSAIDs for acute pulpitis; prompt dental evaluation for restoration or extraction."),
        IndicationItem("ind_251", "Transient ischaemic attack (TIA)", 'T', "Neurology", listOf("Aspirin", "Clopidogrel", "Atorvastatin"), "Dual antiplatelet therapy (Aspirin + Clopidogrel) for 21 days following high-risk TIA (ABCD2 score ≥4)."),
        IndicationItem("ind_252", "Traveller's diarrhea", 'T', "Infectious Diseases & Travel", listOf("Azithromycin", "Ciprofloxacin", "Oral Rehydration Salts"), "Single-dose Azithromycin 1000mg for severe/bloody diarrhea; ORS hydration."),
        IndicationItem("ind_253", "Trigeminal neuralgia", 'T', "Neurology", listOf("Carbamazepine", "Oxcarbazepine", "Baclofen"), "Carbamazepine (100-200mg bid titrating to 600-1200mg/day) is drug of choice."),
        IndicationItem("ind_254", "Tuberculosis (TB)", 'T', "Infectious Diseases & Respiratory", listOf("Isoniazid", "Rifampicin", "Pyrazinamide", "Ethambutol"), "Standard 2HRZE / 4HR regimen with DOTS monitoring per National Tuberculosis Program."),
        IndicationItem("ind_255", "Tuberculous meningitis", 'T', "Infectious Diseases & Neurology", listOf("Isoniazid", "Rifampicin", "Pyrazinamide", "Ethambutol", "Dexamethasone"), "Four-drug intensive HRZE for 2 months then HR for 10 months plus adjunctive Dexamethasone."),
        IndicationItem("ind_256", "Type 1 DM", 'T', "Endocrine & Metabolic", listOf("Insulin Regular", "Insulin Glargine", "Insulin Aspart"), "Basal-bolus intensive insulin therapy with continuous glucose monitoring."),
        IndicationItem("ind_257", "Type 2 DM", 'T', "Endocrine & Metabolic", listOf("Metformin", "Sitagliptin", "Glimepiride", "Insulin Glargine"), "Metformin foundation; add SGLT2i or GLP-1 RA for cardiorenal protection; insulin as needed."),
        IndicationItem("ind_258", "Typhoid fever", 'T', "Infectious Diseases", listOf("Ceftriaxone", "Azithromycin", "Cefixime"), "IV Ceftriaxone 2-3g daily or oral Azithromycin 1g on day 1 then 500mg daily for 7 days."),

        // --- U ---
        IndicationItem("ind_259", "Ulcerative colitis", 'U', "Gastrointestinal", listOf("Mesalamine (5-ASA)", "Tofacitinib", "Prednisolone", "Azathioprine"), "Oral/topical 5-ASA for induction and maintenance of remission; oral steroids for flares; JAK inhibitors (Tofacitinib) or biologics for moderate-severe refractory cases."),
        IndicationItem("ind_260", "Uncomplicated UTI", 'U', "Urology & Infectious", listOf("Nitrofurantoin", "Cotrimoxazole", "Fosfomycin", "Cefixime"), "Nitrofurantoin 100mg PO bid for 5 days or single dose Fosfomycin 3g."),
        IndicationItem("ind_261", "Uncomplicated gonorrhoea", 'U', "Infectious Diseases & STI", listOf("Ceftriaxone", "Azithromycin"), "Single dose Ceftriaxone 500mg-1g IM plus Azithromycin 1g PO."),
        IndicationItem("ind_262", "Unstable angina", 'U', "Cardiovascular & Emergency", listOf("Aspirin", "Clopidogrel", "Enoxaparin", "Atorvastatin", "Bisoprolol"), "DAPT, anticoagulation with therapeutic LMWH, beta-blocker, early invasive strategy."),
        IndicationItem("ind_263", "Upper respiratory tract infections", 'U', "ENT & Respiratory", listOf("Paracetamol", "Cetirizine", "Saline Nasal Spray"), "Predominantly viral; symptomatic relief with antipyretics and hydration; avoid routine antibiotics."),
        IndicationItem("ind_264", "Urethritis", 'U', "Infectious Diseases & STI", listOf("Ceftriaxone", "Azithromycin", "Doxycycline"), "Dual therapy covering Neisseria gonorrhoeae and Chlamydia trachomatis."),
        IndicationItem("ind_265", "Urinary tract infection (UTI)", 'U', "Urology & Infectious", listOf("Nitrofurantoin", "Cefixime", "Ceftriaxone", "Ciprofloxacin"), "First-line Nitrofurantoin 100mg bid for cystitis; Ceftriaxone for pyelonephritis."),
        IndicationItem("ind_266", "Urticaria (Hives)", 'U', "Dermatology & Allergy", listOf("Cetirizine", "Levocetirizine", "Fexofenadine", "Prednisolone"), "Second-generation H1 antihistamines up to 4-fold licensed dose for resistant cases."),

        // --- V, W, Z ---
        IndicationItem("ind_267", "Vaginal candidiasis/Thrush", 'V', "Gastrointestinal & Gynaecology", listOf("Clotrimazole Pessary", "Fluconazole Oral"), "Single dose oral Fluconazole 150mg or Clotrimazole 500mg pessary."),
        IndicationItem("ind_268", "Vaginitis", 'V', "Obstetrics & Gynaecology", listOf("Metronidazole", "Clotrimazole"), "Differentiate bacterial vaginosis (Metronidazole) vs candidiasis (Clotrimazole) vs trichomoniasis."),
        IndicationItem("ind_269", "Variceal haemorrhage", 'V', "Gastrointestinal & Emergency", listOf("Octreotide", "Terlipressin", "Ceftriaxone", "Propranolol"), "Vasoactive drug (Octreotide/Terlipressin), prophylactic Ceftriaxone, urgent endoscopic band ligation."),
        IndicationItem("ind_270", "Venous thromboembolism", 'V', "Cardiovascular & Hematology", listOf("Apixaban", "Enoxaparin", "Warfarin", "Rivaroxaban"), "DOAC or LMWH for minimum 3 months."),
        IndicationItem("ind_271", "Ventricular tachycardia", 'V', "Cardiovascular & Emergency", listOf("Amiodarone", "Lidocaine", "Electrical Cardioversion"), "Synchronized electrical cardioversion if unstable; IV Amiodarone 300mg for stable monomorphic VT."),
        IndicationItem("ind_272", "Vertigo", 'V', "Neurology & ENT", listOf("Betahistine", "Cinnarizine", "Epley Maneuver"), "Canalith repositioning (Epley) for BPPV; Betahistine for Meniere's disease."),
        IndicationItem("ind_273", "Vitamin D Deficiency", 'V', "Endocrine & Metabolic", listOf("Cholecalciferol (Vitamin D3)", "Calcium Carbonate"), "Cholecalciferol 60,000 IU orally once weekly for 8 weeks followed by monthly maintenance."),
        IndicationItem("ind_274", "Vulvovaginal candidiasis", 'V', "Obstetrics & Gynaecology", listOf("Fluconazole", "Clotrimazole Pessary"), "Fluconazole 150mg single dose; topical clotrimazole safe in pregnancy."),
        IndicationItem("ind_275", "Wound infection", 'W', "Surgery & Dermatology", listOf("Amoxicillin + Clavulanate", "Cloxacillin", "Povidone Iodine"), "Suture removal, drainage, debridement; targeted antimicrobials for spreading cellulitis."),
        IndicationItem("ind_276", "Wound sepsis", 'W', "Surgery & Critical Care", listOf("Piperacillin + Tazobactam", "Vancomycin", "Metronidazole"), "Immediate aggressive surgical source control plus broad-spectrum parenteral antibiotics."),
        IndicationItem("ind_277", "Zollinger-Ellison syndrome", 'Z', "Gastrointestinal & Endocrine", listOf("Pantoprazole", "Omeprazole", "Octreotide"), "High-dose proton pump inhibitors (e.g. Pantoprazole 80-160mg daily) to control acid hypersecretion.")
    )
}
